import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.CyZTVJbV.js";const w=JSON.parse('{"title":"Tool comparison","description":"","frontmatter":{},"headers":[],"relativePath":"COMPARISON.ja.md","filePath":"COMPARISON.ja.md"}'),r={name:"COMPARISON.ja.md"};function d(o,a,s,n,p,c){return t(),i("div",null,[...a[0]||(a[0]=[l(`<h1 id="tool-comparison" tabindex="-1">Tool comparison <a class="header-anchor" href="#tool-comparison" aria-label="Permalink to &quot;Tool comparison&quot;">​</a></h1><blockquote><p><a href="./COMPARISON">🇬🇧 English</a> • <a href="./COMPARISON.ja">🇯🇵 日本語</a></p></blockquote><p>本ドキュメントは kiwa を既存の wallet E2E 周辺ツールと比較したい利用者向けです。 内容は v0.1.0 時点、すなわち 2026-06 時点の kiwa の機能と、 各公式 repository / docs で公開されている役割を基準に整理しています。 結論だけ先に言うと、kiwa は anvil を使う headless E2E の安定運用に寄せた立ち位置です。</p><h2 id="比較表" tabindex="-1">比較表 <a class="header-anchor" href="#比較表" aria-label="Permalink to &quot;比較表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>観点</th><th>Synpress</th><th>dappwright</th><th>wallet-mock</th><th>kiwa</th></tr></thead><tbody><tr><td>主対象</td><td>実 wallet 連携を含む E2E</td><td>実 MetaMask / Coinbase Wallet 拡張の自動化</td><td>headless wallet 注入</td><td>ローカル chain 前提の dApp E2E</td></tr><tr><td>ブラウザ側</td><td>Playwright / Cypress + wallet 拡張連携</td><td>Playwright + 拡張機能 download / unpack helper</td><td>Playwright へ mock wallet を注入</td><td>Playwright へ <code>window.ethereum</code> を注入</td></tr><tr><td>chain backend</td><td>実 wallet と組み合わせる任意 backend</td><td>実 wallet と組み合わせる任意 backend</td><td>mock 応答または任意 transport</td><td>anvil を test ごとに起動</td></tr><tr><td>署名 / 送金</td><td>wallet UI を経由</td><td>wallet UI を経由</td><td>mock または transport 経由</td><td>anvil dev account で直接処理</td></tr><tr><td>CI 安定性</td><td>中</td><td>中 (MetaMask version 依存)</td><td>高</td><td>高</td></tr><tr><td>向く場面</td><td>wallet UX 確認</td><td>軽量な拡張機能自動化</td><td>provider 差し替え検証</td><td>ローカル chain での接続フロー検証</td></tr></tbody></table><p>どれが常に上位という関係ではなく、確認したい対象が違います。 wallet UI、provider mock、ローカル chain のどこに重心を置くかで選ぶのが実用的です。</p><h2 id="kiwa-の位置づけ" tabindex="-1">kiwa の位置づけ <a class="header-anchor" href="#kiwa-の位置づけ" aria-label="Permalink to &quot;kiwa の位置づけ&quot;">​</a></h2><p>kiwa は次の 3 点を優先しています。</p><ul><li>anvil を test 単位で直接起動できること</li><li>browser extension を持ち込まず headless で回せること</li><li>EIP-1193 の最小コアを fixture として使い回せること</li></ul><p>その代わり、wallet popup の文言確認や拡張 UI の操作再現は対象外です。 README の先頭で「実 MetaMask UI 検証は別ツールへ分離」としている理由もここにあります。</p><h2 id="使い分けガイド" tabindex="-1">使い分けガイド <a class="header-anchor" href="#使い分けガイド" aria-label="Permalink to &quot;使い分けガイド&quot;">​</a></h2><h3 id="synpress-を選ぶ場合" tabindex="-1">Synpress を選ぶ場合 <a class="header-anchor" href="#synpress-を選ぶ場合" aria-label="Permalink to &quot;Synpress を選ぶ場合&quot;">​</a></h3><ul><li>実 wallet UI の接続確認、承認、拒否まで含めて見たい</li><li>dApp 側だけでなく browser extension 側の表示崩れも拾いたい</li><li>Playwright または Cypress と wallet 拡張の組み合わせを維持したい</li></ul><p>Synpress は wallet 実体との統合を取り込みたいときに強い候補です。 一方で browser setup と extension 依存が入るため、headless 実行だけを素早く回す用途では過剰になりやすいです。</p><h3 id="dappwright-を選ぶ場合" tabindex="-1">dappwright を選ぶ場合 <a class="header-anchor" href="#dappwright-を選ぶ場合" aria-label="Permalink to &quot;dappwright を選ぶ場合&quot;">​</a></h3><ul><li>MetaMask または Coinbase Wallet 拡張を自動化する軽量な Playwright helper が欲しい</li><li>Synpress 全体を取り込まず、拡張機能の download / unpack / load helper だけが欲しい</li><li>dappwright が対応する特定の MetaMask version を pin して使うことに抵抗がない</li></ul><p>dappwright は scope の広さで言うと Synpress と wallet-mock の中間に位置します。 E2E framework 全体ではなく、拡張機能の自動化を Playwright helper として薄く束ねた構成で、Synpress より表面積を小さく抑えられます。 ただし実 MetaMask 拡張の自動化は最近の MetaMask version に対して構造的な脆さがあるため (次節を参照)、CI 安定性の注意点は Synpress と同様に当てはまります。</p><h3 id="wallet-mock-を選ぶ場合" tabindex="-1">wallet-mock を選ぶ場合 <a class="header-anchor" href="#wallet-mock-を選ぶ場合" aria-label="Permalink to &quot;wallet-mock を選ぶ場合&quot;">​</a></h3><ul><li>provider を headless に差し込みたい</li><li>mock 応答を細かく差し替えたい</li><li>実 chain 接続よりも dApp 側分岐の確認を優先したい</li></ul><p>wallet-mock は Playwright に wallet を注入する発想が近い一方で、 anvil lifecycle やローカル chain の隔離は利用側で組む前提です。 transport を自由に差し替えたい test には向きます。</p><h3 id="kiwa-を選ぶ場合" tabindex="-1">kiwa を選ぶ場合 <a class="header-anchor" href="#kiwa-を選ぶ場合" aria-label="Permalink to &quot;kiwa を選ぶ場合&quot;">​</a></h3><ul><li>自分でセットアップした anvil のローカル chain で dApp E2E を試したい</li><li>provider の最小面だけあれば十分で、wallet UI までは不要</li><li><code>window.ethereum</code> の request / event を page から素直に叩きたい</li><li>Playwright fixture だけで起動、注入、終了まで閉じたい</li></ul><p>kiwa は「ローカル chain 上で dApp 自体を headless に検証する」用途に最も合います。 <code>eth_requestAccounts</code> から <code>eth_sendTransaction</code> までの流れを 1 つの fixture にまとめたいなら、 この repo の <code>examples/basic-connect</code> が最短の導入例です。</p><h2 id="選定の目安" tabindex="-1">選定の目安 <a class="header-anchor" href="#選定の目安" aria-label="Permalink to &quot;選定の目安&quot;">​</a></h2><ol><li>wallet UI の真偽が重要なら Synpress または dappwright</li><li>provider の差し替えと mock 制御が主目的なら wallet-mock</li><li>ローカル chain 上の dApp 挙動と CI 安定性を同時に欲しいなら kiwa</li></ol><h2 id="kiwa-が-metamask-拡張自動化を取り込まない理由" tabindex="-1">kiwa が MetaMask 拡張自動化を取り込まない理由 <a class="header-anchor" href="#kiwa-が-metamask-拡張自動化を取り込まない理由" aria-label="Permalink to &quot;kiwa が MetaMask 拡張自動化を取り込まない理由&quot;">​</a></h2><p>kiwa は real MetaMask 拡張の自動化を自前で実装せず、Synpress や dappwright に意図的に委ねています。 これは PoC 段階で 10 種類のアプローチを最後まで走らせた結果、OSS 一個でルートできない共通の構造的ブロッカーに辿り着いたためです。</p><p>10 試行に共通する根本原因は、自動化されたブラウザ下で MetaMask の <code>chrome.sidePanel</code> API が undefined となり、click handler が <code>catch</code> 分岐に落ち、wallet-ready コンポーネントが <code>H &amp;&amp; q</code> ガードによって <code>disabled</code> を保持し続けるため navigation dispatch が発火しないという点です。 README onboarding そのまま、wait 延長、<code>manage-default-settings</code> の bypass、<code>disabled</code> 属性の剥奪、headful Chromium、v13.17.0 への downgrade、Synpress 完全 install、MetaMask 公式 e2e flow の vendor、dappwright の vendor、暗号化済み vault を <code>chrome.storage</code> に直書き、の 10 アプローチがすべて同じブロッカーで停止しました。</p><p>ここから読み取れるのは「特定のライブラリが壊れている」ことではなく、構造的なブロッカーが MetaMask 側にあるということです。 real MetaMask 拡張を全自動化したい library は upstream の変更を密に追従し、新版 MetaMask に対する脆さを許容する必要があり、これは継続的な保守コストになります。 kiwa は代わりに anvil 上の contract / UI logic 検証と最小の <code>window.ethereum</code> 注入に集中し、wallet UX 検証が必要なユーザーには Synpress や dappwright を案内する立場を取ります。</p><p>複数併用も現実的です。 たとえば日常の回帰は kiwa、release 前の wallet UX 確認だけ Synpress、という分担は十分ありえます。 wallet 層と dApp 層を別々に検証したい team ほど、この分担の効果が出やすくなります。</p><h2 id="kiwa-が向かないケース" tabindex="-1">kiwa が向かないケース <a class="header-anchor" href="#kiwa-が向かないケース" aria-label="Permalink to &quot;kiwa が向かないケース&quot;">​</a></h2><ul><li>拡張 popup のボタン文言や配置そのものを検証したい</li><li>複数 wallet 拡張の競合や browser profile 差分を見たい</li><li>provider を完全 mock にして chain 接続を切り離したい</li></ul><p>この領域では、kiwa の「anvil を起点にした最小 provider」という設計がそのまま制約になります。 wallet UI の再現性が主目的なら Synpress、 transport 差し替えの自由度が主目的なら wallet-mock の方が設計意図に合います。</p><h2 id="kiwa-を選ぶときの確認項目" tabindex="-1">kiwa を選ぶときの確認項目 <a class="header-anchor" href="#kiwa-を選ぶときの確認項目" aria-label="Permalink to &quot;kiwa を選ぶときの確認項目&quot;">​</a></h2><ul><li>anvil を利用できる環境があるか</li><li>ローカル anvil chain を前提に test を組めるか</li><li>wallet 拡張 UI の確認を別レイヤへ分離できるか</li><li><code>viem</code> と Playwright を host project 側で管理したいか</li></ul><p>この 4 点に無理がなければ、kiwa の設計と相性が良い可能性が高いです。</p><h2 id="ai-仕様書ベース-test-生成軸の比較" tabindex="-1">AI / 仕様書ベース test 生成軸の比較 <a class="header-anchor" href="#ai-仕様書ベース-test-生成軸の比較" aria-label="Permalink to &quot;AI / 仕様書ベース test 生成軸の比較&quot;">​</a></h2><p>上の節は dApp E2E fixture としての比較ですが、 kiwa は Claude Code skill (<code>/kiwa-design</code> / <code>/kiwa-forge</code> / <code>/kiwa-hardhat</code> / <code>/kiwa-play</code> / <code>/kiwa-vitest</code> / <code>/kiwa-api</code> / <code>/kiwa-review</code> / <code>/kiwa-test</code>) も持ち、 1 つの仕様書から 4 layer (contract / unit / integration / e2e) を横断して test を設計・生成します。 本節ではその側面を比較します。</p><table tabindex="0"><thead><tr><th>観点</th><th>hardhat-test-suite-generator</th><th>Foundry / Hardhat AI plugin (2026)</th><th>Claude Code spec-driven dev</th><th>kiwa skill chain</th></tr></thead><tbody><tr><td>アプローチ</td><td>contract ABI から静的 template scaffold</td><td>LLM で fuzz seed / invariant 提案 plugin</td><td>自由形式 spec → test → code 反復</td><td>11 観点 spec → 4 layer test code</td></tr><tr><td>scope</td><td>Hardhat contract test のみ</td><td>contract layer (fuzz + invariant) のみ</td><td>汎用、 言語非依存</td><td>contract + dApp e2e + unit + integration</td></tr><tr><td>spec 形式</td><td>なし (ABI 駆動)</td><td>なし (heuristic)</td><td>自由形式 markdown</td><td>固定 9 section / 9 column markdown</td></tr><tr><td>layer cover</td><td>1 (Hardhat)</td><td>1 (Foundry or Hardhat の fuzz / invariant)</td><td>project ごとに決定</td><td>4 (contract / unit / integration / e2e)</td></tr><tr><td>review loop</td><td>なし</td><td>なし</td><td>手動</td><td><code>/kiwa-review</code> が 11 観点 + spec drift を check</td></tr><tr><td>適性</td><td>Hardhat の test boilerplate scaffold</td><td>既存 Foundry repo の fuzz / invariant 補強</td><td>汎用 LLM 支援開発</td><td>contract + e2e を同時に扱う dApp project</td></tr></tbody></table><h3 id="kiwa-skill-chain-が活きる場面" tabindex="-1">kiwa skill chain が活きる場面 <a class="header-anchor" href="#kiwa-skill-chain-が活きる場面" aria-label="Permalink to &quot;kiwa skill chain が活きる場面&quot;">​</a></h3><ul><li>spec → test → review → coverage report を 1 コマンド (<code>/kiwa-test --example {name}</code>) で流したい</li><li>1 枚の 9 column spec 表から Foundry / Hardhat / Playwright / Vitest を並列駆動したい</li><li>11 観点 (正常系 / 異常系 / 境界値 / 状態遷移 / 権限 / 入力バリデーション / 冪等性 / 並行処理 / 性能 / セキュリティ / 回帰) を dApp test suite に明示適用したい</li></ul><h3 id="他ツールが向く場面" tabindex="-1">他ツールが向く場面 <a class="header-anchor" href="#他ツールが向く場面" aria-label="Permalink to &quot;他ツールが向く場面&quot;">​</a></h3><ul><li>Hardhat contract test の scaffold だけ欲しい → <code>hardhat-test-suite-generator</code> の方が軽量</li><li>既存 Foundry repo に fuzz seed を足したいだけ → Foundry AI plugin が適合</li><li>dApp 固有の事情がない汎用 LLM 支援 dev loop → Claude Code spec-driven dev をそのまま使う</li></ul><h2 id="kiwa-独自の領域" tabindex="-1">kiwa 独自の領域 <a class="header-anchor" href="#kiwa-独自の領域" aria-label="Permalink to &quot;kiwa 独自の領域&quot;">​</a></h2><p>両軸 (dApp E2E fixture + spec-driven test 生成) を比較した結果、 kiwa の独自性は <strong>1 入口から 4 layer chain</strong> をすべて回す点にあります。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/kiwa-design (Layer 1)</span></span>
<span class="line"><span>  ├─ /kiwa-forge        → Foundry .t.sol</span></span>
<span class="line"><span>  ├─ /kiwa-hardhat      → Hardhat .test.ts</span></span>
<span class="line"><span>  ├─ /kiwa-play         → Playwright .spec.ts (@kiwa/dapp fixture を使用)</span></span>
<span class="line"><span>  ├─ /kiwa-vitest       → Vitest .test.ts (unit)</span></span>
<span class="line"><span>  ├─ /kiwa-api          → Vitest + msw / supertest (integration)</span></span>
<span class="line"><span>  └─ /kiwa-review       → spec vs 実装 drift + 11 観点 cover を check</span></span></code></pre></div><p>執筆時点で両軸どちらの競合も 4 layer (contract + unit + integration + e2e) を 1 つの spec から横断する例は確認できませんでした。</p><h2 id="関連" tabindex="-1">関連 <a class="header-anchor" href="#関連" aria-label="Permalink to &quot;関連&quot;">​</a></h2><ul><li><a href="https://github.com/Synthetixio/synpress" target="_blank" rel="noreferrer">Synpress repository</a></li><li><a href="https://github.com/TenKeyLabs/dappwright" target="_blank" rel="noreferrer">dappwright repository</a></li><li><a href="https://github.com/johanneskares/wallet-mock" target="_blank" rel="noreferrer">wallet-mock repository</a></li><li><a href="https://github.com/ahmedali8/hardhat-test-suite-generator" target="_blank" rel="noreferrer">hardhat-test-suite-generator</a></li><li><a href="https://www.augmentcode.com/guides/claude-code-spec-driven-development" target="_blank" rel="noreferrer">Claude Code spec-driven development</a></li><li><a href="https://book.getfoundry.sh/anvil/" target="_blank" rel="noreferrer">Foundry anvil docs</a></li><li><a href="./RPC">RPC.md</a></li><li><a href="./../README">README.md</a></li></ul>`,49)])])}const k=e(r,[["render",d]]);export{w as __pageData,k as default};
